#!/usr/bin/env bash
# Make paper/ read-only except the machine-generated subfolders.
#
# figs/ and tabs/ stay writable: they are regenerated by plots/*.py and
# scripts/make_mib_*_table.py. Everything else (prose, captions, .bib, the
# Overleaf-built pdf/log, the ICLR style files) is the author's.
#
# Re-run after every `git pull` in paper/: git checks out a changed file by
# unlinking and recreating it, so upstream-modified files come back mode 664.
set -euo pipefail

PAPER="${1:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/paper}"
cd "$PAPER"

find . -path ./.git -prune -o -path ./figs -prune -o -path ./tabs -prune \
     -o -type f -print0 | xargs -0 chmod a-w

echo "locked $(find . -path ./.git -prune -o -path ./figs -prune -o -path ./tabs -prune -o -type f -print | wc -l) files under $PAPER (figs/, tabs/ left writable)"
